void file_browser_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_file_browser_select_obj_t * p_screen_param;
    lv_obj_t *      list = get_file_browser_select_list_obj(ui_Screen);
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_file_browser_select_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("file_browser_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,1);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                if (_lv_ll_get_len(&p_screen_param->p_win_param->ll) > 1)
                    exit_cur_dir(p_screen_param->p_win_param);
                else 
                    alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
            {
                lv_obj_t *      obj_img;
                int             is_folder;
                char            path[APP_FS_MAX_PATH];
                char *          d_name;

                if (child_cnt == 0)
                    break;

                get_focus_obj       = lv_obj_get_child(list,child_id);
                obj_img             = lv_obj_get_child(get_focus_obj,0);
                is_folder           = (int) lv_obj_get_user_data(obj_img);
                label               = lv_obj_get_child(get_focus_obj,1);
                d_name              = lv_label_get_text(label);

                strcpy(path,p_screen_param->cur_folder_path);
                strcat(path,"/");
                strcat(path,d_name);

                if (is_folder) {
                    enter_next_dir(path,p_screen_param->p_win_param);
                    }
                else {
                    open_browser_file(path);
                    }
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}



static void remind_timer_callback_file_browser(screen_remind_param_t * p_screen_remind_param)
{
    list_file_browser_win_param_t * p_param;

    p_param             = p_screen_remind_param->user_data;

    enter_next_dir(NULL,p_param);

}




lv_obj_t * ui_ScreenFileBrowser_screen_active(lv_obj_t * win,void * param)
{
    screen_remind_param_t screen_remind_param;
    lv_obj_t *      ui_screen;
    list_file_browser_win_param_t * p_param;

    p_param             = lv_mem_alloc(sizeof(list_file_browser_win_param_t));
    p_param->ui_remind  = NULL;
    p_param->focus_status = 0;

    _lv_ll_init(& (p_param->ll),sizeof(file_browser_node_t));

    ui_screen_remind_param_init(&screen_remind_param);
    screen_remind_param.str = "正打开";
    screen_remind_param.tiemr_delay = 500;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_file_browser;
    screen_remind_param.user_data = p_param;
    screen_remind_param.self_destory_flag = 0;
    screen_remind_param.key_exit_enable = 0;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    p_param->ui_remind  = ui_screen;

    lv_obj_set_user_data(win,p_param);

    return ui_screen;
}


void ui_ScreenFileBrowser_screen_deactive(lv_obj_t * win,void * param)
{
    list_file_browser_win_param_t * p_param;
    file_browser_node_t * p_cur_node;

    p_param             = (list_file_browser_win_param_t *) lv_obj_get_user_data(win);
    ui_screen_remind_uninit(p_param->ui_remind);

    p_cur_node          = _lv_ll_get_tail(& (p_param->ll));

    for (int i = 0; p_cur_node != NULL; i++) {
        ui_ScreenFileBrowser_screen_uninit(p_cur_node->ui_screen,NULL);
        p_cur_node->ui_screen = NULL;

        _lv_ll_remove(& (p_param->ll),p_cur_node);
        lv_mem_free((void *) p_cur_node);

        p_cur_node          = _lv_ll_get_tail(& (p_param->ll));
        }

    lv_mem_free(p_param);
    lv_obj_set_user_data(win,NULL);
}


void ui_ScreenFileBrowser_win_focus(lv_obj_t * win,void * param)
{
    list_file_browser_win_param_t * p_param;

    p_param             = (list_file_browser_win_param_t *) lv_obj_get_user_data(win);
    file_browser_node_t * p_cur_node;
    lv_obj_t *      ui_screen = NULL;

    p_cur_node          = _lv_ll_get_tail(& (p_param->ll));

    if (p_cur_node != NULL)
        ui_screen = p_cur_node->ui_screen;
    else if (p_param->ui_remind)
        ui_screen = p_param->ui_remind;

    if (ui_screen)
        lv_disp_load_scr(ui_screen);

    p_param->focus_status = 1;
}

void ui_ScreenFileBrowser_win_defocus(lv_obj_t * win,void * param)
{
    list_file_browser_win_param_t * p_param;

    p_param             = lv_obj_get_user_data(win);

    p_param->focus_status = 0;

}

